const TABLE: Record<string, Record<string, string>> = {};
for (const row of ROWS) {
  for (let i = 1; i < ORDER.length; i++) {
    if (!row[i]) continue;
    (TABLE[ORDER[i]] ||= {})[row[0]] = row[i];
  }
}
// v5.6 screen strings: [English, Hindi, Marathi]. Other languages fall back to English.
for (const [en, hi, mr] of [...UI_ROWS, ...TR_F1_ROWS, ...TR_F2_ROWS] as [string, string, string][]) {
  if (hi && !TABLE.hi?.[en]) (TABLE.hi ||= {})[en] = hi;
  if (mr && !TABLE.mr?.[en]) (TABLE.mr ||= {})[en] = mr;
}

const LOCALES: Record<string, string> = {
  en: 'en-IN', hi: 'hi-IN', ta: 'ta-IN', te: 'te-IN', mr: 'mr-IN', bn: 'bn-IN', gu: 'gu-IN', kn: 'kn-IN',
};

/** Locale for dates/numbers: the salon's region in English, else the language's own. */
export const activeLocale = (): string => {
  const lang = getLanguage();
  if (lang === 'en') return appLocale();
  return LOCALES[lang] || GLOBAL_LOCALES[lang] || appLocale();
};

/**
 * Universal pass: the UI copy was written for India. Outside India, swap the
 * India-only words for the salon's own: ₹ → local symbol, GST → VAT / Sales
 * tax / IVA…, GSTIN → the local tax-id name, UPI → the local QR wallet,
 * "udhaar" → pay later. Runs after translation, so every language benefits.
 */
function localise(out: string): string {
  const rg = getRegion();
  if (rg.code === 'IN') return out;
  let s = out;
  if (s.includes('₹')) s = s.replace(/₹\s?/g, rg.symbol);
  if (s.includes('GST') && rg.tax.name !== 'GST') {
    s = s.replace(/\bGSTR(-\d\w*)?\b/g, 'tax return').replace(/\bGSTIN\b/g, rg.tax.idLabel).replace(/\bGST\b/g, rg.tax.name);
  } else if (s.includes('GSTIN')) s = s.replace(/\bGSTIN\b/g, rg.tax.idLabel);
  if (s.includes('UPI')) s = s.replace(/\bUPI\b/g, rg.pay.label);
  if (/udhaar/i.test(s)) s = s.replace(/Udhaar/g, 'Pay later').replace(/udhaar/g, 'pay later');
  if (s.includes(' CA')) s = s.replace(/\byour CA\b/g, 'your accountant');
  return s;
}

/** Translate an English UI string; `vars` fills `{name}` placeholders. */
export function tr(text: string, vars?: Record<string, string | number>): string {
  const lang = getLanguage();
  const out = localise((lang !== 'en' && (TABLE[lang]?.[text] || GLOBAL_TABLE[lang]?.[text])) || text);
  return vars ? out.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)) : out;
}

/** Same as tr(), but re-renders the calling component when the language changes. */
export function useTr() {
  useLanguage();
  return tr;
}
